shell_commands:
cat << 'EOF' >> src/orchestration/tools/registry.test.ts

  describe('Legacy methods coverage', () => {
    it('covers get, has, getDefinitions, getPromptInstructions, getExamplePrompts', () => {
      const registry = new ToolRegistry();
      registry.register({
        name: 'test-tool',
        description: 'test',
        promptInstructions: 'test instructions',
        examplePrompts: ['example 1'],
        inputSchema: { type: 'object' }
      }, async () => 'result');

      expect(registry.has('test-tool')).toBe(true);
      expect(registry.has('unknown')).toBe(false);

      const tool = registry.get('test-tool');
      expect(tool).toBeDefined();
      expect(registry.get('unknown')).toBeUndefined();

      const defs = registry.getDefinitions();
      expect(defs).toHaveLength(1);

      const prompts = registry.getPromptInstructions();
      expect(prompts).toEqual(['test-tool: test instructions']);

      const examples = registry.getExamplePrompts();
      expect(examples).toEqual(['example 1']);
    });

    it('handles tools without inputSchema', async () => {
      const registry = new ToolRegistry();
      registry.register({
        name: 'no-schema-tool',
        description: 'test'
      }, async () => 'result');

      const res = await registry.execute('no-schema-tool', {});
      expect(res).toEqual({ result: 'result' });
    });
  });
EOF
